    Encryption.add_member(:constant_initialization_vector, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::String, location_name: 'ConstantInitializationVector', traits: {"smithy.api#documentation" => "<p>A 128-bit, 16-byte hex value represented by a 32-character string, used in conjunction with the key for encrypting content. If you don't specify a value, then MediaPackage creates the constant initialization vector (IV).</p>", "smithy.api#length" => {"min" => 32, "max" => 32}, "smithy.api#pattern" => "^[0-9a-fA-F]+$"}))
    Encryption.add_member(:encryption_method, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionMethod, location_name: 'EncryptionMethod', traits: {"smithy.api#documentation" => "<p>The encryption method to use.</p>", "smithy.api#required" => {}}))
    Encryption.add_member(:key_rotation_interval_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Integer, location_name: 'KeyRotationIntervalSeconds', traits: {"smithy.api#documentation" => "<p>The frequency (in seconds) of key changes for live workflows, in which content is streamed real time. The service retrieves content keys before the live content begins streaming, and then retrieves them as needed over the lifetime of the workflow. By default, key rotation is set to 300 seconds (5 minutes), the minimum rotation interval, which is equivalent to setting it to 300. If you don't enter an interval, content keys aren't rotated.</p>\n         <p>The following example setting causes the service to rotate keys every thirty minutes: <code>1800</code>\n         </p>", "smithy.api#range" => {"min" => 300, "max" => 31536000}}))
    Encryption.add_member(:cmaf_exclude_segment_drm_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Boolean, location_name: 'CmafExcludeSegmentDrmMetadata', traits: {"smithy.api#documentation" => "<p>Excludes SEIG and SGPD boxes from segment metadata in CMAF containers.</p>\n         <p>When set to <code>true</code>, MediaPackage omits these DRM metadata boxes from CMAF segments, which can improve compatibility with certain devices and players that don't support these boxes.</p>\n         <p>Important considerations:</p>\n         <ul>\n            <li>\n               <p>This setting only affects CMAF container formats</p>\n            </li>\n            <li>\n               <p>Key rotation can still be handled through media playlist signaling</p>\n            </li>\n            <li>\n               <p>PSSH and TENC boxes remain unaffected</p>\n            </li>\n            <li>\n               <p>Default behavior is preserved when this setting is disabled</p>\n            </li>\n         </ul>\n         <p>Valid values: <code>true</code> | <code>false</code>\n         </p>\n         <p>Default: <code>false</code>\n         </p>"}))
    Encryption.add_member(:speke_key_provider, Smithy::Schema::Shapes::ShapeRef.new(shape: SpekeKeyProvider, location_name: 'SpekeKeyProvider', traits: {"smithy.api#documentation" => "<p>The parameters for the SPEKE key provider.</p>", "smithy.api#required" => {}}))
    Encryption.type = Types::Encryption
    EncryptionContractConfiguration.add_member(:preset_speke20_audio, Smithy::Schema::Shapes::ShapeRef.new(shape: PresetSpeke20Audio, location_name: 'PresetSpeke20Audio', traits: {"smithy.api#documentation" => "<p>A collection of audio encryption presets.</p>\n         <p>Value description: </p>\n         <ul>\n            <li>\n               <p>PRESET-AUDIO-1 - Use one content key to encrypt all of the\n               audio tracks in your stream.</p>\n            </li>\n            <li>\n               <p>PRESET-AUDIO-2 - Use one content key to encrypt all of the\n               stereo audio tracks and one content key to encrypt all of the multichannel\n               audio tracks.</p>\n            </li>\n            <li>\n               <p>PRESET-AUDIO-3 - Use one content key to encrypt all of the\n               stereo audio tracks, one content key to encrypt all of the multichannel audio\n               tracks with 3 to 6 channels, and one content key to encrypt all of the\n               multichannel audio tracks with more than 6 channels.</p>\n            </li>\n            <li>\n               <p>SHARED - Use the same content key for all of the audio and\n               video tracks in your stream.</p>\n            </li>\n            <li>\n               <p>UNENCRYPTED - Don't encrypt any of the audio tracks in your\n               stream.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    EncryptionContractConfiguration.add_member(:preset_speke20_video, Smithy::Schema::Shapes::ShapeRef.new(shape: PresetSpeke20Video, location_name: 'PresetSpeke20Video', traits: {"smithy.api#documentation" => "<p>A collection of video encryption presets.</p>\n         <p>Value description: </p>\n         <ul>\n            <li>\n               <p>PRESET-VIDEO-1 - Use one content key to encrypt all of the video\n               tracks in your stream.</p>\n            </li>\n            <li>\n               <p>PRESET-VIDEO-2 - Use one content key to encrypt all of the SD\n               video tracks and one content key for all HD and higher resolutions video\n               tracks.</p>\n            </li>\n            <li>\n               <p>PRESET-VIDEO-3 - Use one content key to encrypt all of the SD\n               video tracks, one content key for HD video tracks and one content key for all\n               UHD video tracks.</p>\n            </li>\n            <li>\n               <p>PRESET-VIDEO-4 - Use one content key to encrypt all of the SD\n               video tracks, one content key for HD video tracks, one content key for all UHD1\n               video tracks and one content key for all UHD2 video tracks.</p>\n            </li>\n            <li>\n               <p>PRESET-VIDEO-5 - Use one content key to encrypt all of the SD\n               video tracks, one content key for HD1 video tracks, one content key for HD2\n               video tracks, one content key for all UHD1 video tracks and one content key for\n               all UHD2 video tracks.</p>\n            </li>\n            <li>\n               <p>PRESET-VIDEO-6 - Use one content key to encrypt all of the SD\n               video tracks, one content key for HD1 video tracks, one content key for HD2\n               video tracks and one content key for all UHD video tracks.</p>\n            </li>\n            <li>\n               <p>PRESET-VIDEO-7 - Use one content key to encrypt all of the SD+HD1\n               video tracks, one content key for HD2 video tracks and one content key for all\n               UHD video tracks.</p>\n            </li>\n            <li>\n               <p>PRESET-VIDEO-8 - Use one content key to encrypt all of the SD+HD1\n               video tracks, one content key for HD2 video tracks, one content key for all\n               UHD1 video tracks and one content key for all UHD2 video tracks.</p>\n            </li>\n            <li>\n               <p>SHARED - Use the same content key for all of the video and audio\n               tracks in your stream.</p>\n            </li>\n            <li>\n               <p>UNENCRYPTED - Don't encrypt any of the video tracks in your stream.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
