    FilterConfiguration.add_member(:end, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Timestamp, location_name: 'End', traits: {"smithy.api#documentation" => "<p>Optionally specify the end time for all of your manifest egress requests. When you include end time, note that you cannot use end time query parameters for this manifest's endpoint URL.</p>"}))
    FilterConfiguration.add_member(:time_delay_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Integer, location_name: 'TimeDelaySeconds', traits: {"smithy.api#documentation" => "<p>Optionally specify the time delay for all of your manifest egress requests. Enter a value that is smaller than your endpoint's startover window. When you include time delay, note that you cannot use time delay query parameters for this manifest's endpoint URL.</p>", "smithy.api#range" => {"min" => 0, "max" => 1209600}}))
