    ScteHls.add_member(:ad_marker_hls, Smithy::Schema::Shapes::ShapeRef.new(shape: AdMarkerHls, location_name: 'AdMarkerHls', traits: {"smithy.api#documentation" => "<p>Ad markers indicate when ads should be inserted during playback. If you include ad markers in the content stream in your upstream encoders, then you need to inform MediaPackage what to do with the ad markers in the output. Choose what you want MediaPackage to do with the ad markers.</p>\n         <p>Value description: </p>\n         <ul>\n            <li>\n               <p>DATERANGE - Insert EXT-X-DATERANGE tags to signal ad and program transition events in TS and CMAF manifests. If you use DATERANGE, you must set a programDateTimeIntervalSeconds value of 1 or higher. To learn more about DATERANGE, see <a href=\"http://docs.aws.amazon.com/mediapackage/latest/ug/scte-35-ad-marker-ext-x-daterange.html\">SCTE-35 Ad Marker EXT-X-DATERANGE</a>.</p>\n            </li>\n         </ul>"}))
